import { render, screen, fireEvent } from '@testing-library/react'
import { describe, it, expect } from 'vitest'
import { Game } from './Game'
import '@testing-library/jest-dom'

describe('Game Component', () => {
    it('shakes the row when Enter is pressed with an empty guess', () => {
        render(<Game solution="valid" />)
        fireEvent.keyDown(document, { key: 'Enter', code: 'Enter' })
        const row = screen.getByTestId('row-0')
        expect(row).toHaveClass('animate-shake')
    })

    it('shakes the row when on-screen Enter is clicked with an empty guess', () => {
        render(<Game solution="valid" />)
        const row = screen.getByTestId('row-0')
        const enterKey = screen.getByRole('button', { name: /enter/i })
        fireEvent.click(enterKey)
        expect(row).toHaveClass('animate-shake')
    })

    it('does not shake the row when a valid guess is entered and Enter is pressed', () => {
        render(<Game solution="VALID" />)
        const row = screen.getByTestId('row-0')
        for (const key of 'VALID') {
            fireEvent.keyDown(document, { key, code: `Key${key}` })
        }
        fireEvent.keyDown(document, { key: 'Enter', code: 'Enter' })
        expect(row).not.toHaveClass('animate-shake')
    })
})

import { useCallback, useEffect, useRef, useState } from "react";
import {
    BACKSPACE,
    ENTER,
    GAME_ROUNDS,
    GAME_WORD_LENGTH,
    LetterState,
} from "../constants";
import { GuessRow } from "./GuessRow";
import { Keyboard } from "./Keyboard";
import { useCurrentGuessReducer } from "../hooks/useCurrentGuessReducer";
import { isValidWord } from "../utils/IsValidWord";
import { getTileStates } from "../utils/getTileStates";
import {
    getStoredGameState,
    setStoredGameState,
} from "../utils/gameStateStorage";

type Props = {
    solution: string;
};

type GameCompletionState = "active" | "won" | "lost";

/**
 * The main game component for the Rune Master word game.
 */
export const Game = ({ solution }: Props) => {
    // State
    const [currentGuess, dispatch] = useCurrentGuessReducer();
    const [guesses, setGuesses] = useState<string[]>(getStoredGameState());
    const [gameCompletionState, setGameCompletion] = useState<GameCompletionState>("active");
    const [toastText, setToastText] = useState<string>("");
    const [shakeCurrentRow, setShakeCurrentRow] = useState<boolean>(false);

    // Refs for timeouts
    const toastTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);
    const shakeTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);

    // --- Utility Callbacks ---

    // Update guesses and persist to storage
    const setGuessesCallback = useCallback(
        (newGuesses: string[]) => {
            setGuesses(newGuesses);
            setStoredGameState(newGuesses);
        },
        []
    );

    // Show toast notification for a limited time
    const showToast = useCallback((text: string) => {
        if (toastTimeout.current) clearTimeout(toastTimeout.current);
        setToastText(text);
        toastTimeout.current = setTimeout(() => setToastText(""), 5000);
    }, []);

    // Trigger shake animation for current guess row
    const shakeCurrentGuess = useCallback(() => {
        if (shakeTimeout.current) clearTimeout(shakeTimeout.current);
        setShakeCurrentRow(true);
        shakeTimeout.current = setTimeout(() => setShakeCurrentRow(false), 1000);
    }, []);

    // --- Game Logic ---

    // Handle guess submission
    const submitWord = useCallback(() => {
        if (currentGuess.length !== GAME_WORD_LENGTH) {
            showToast("Not enough letters");
            shakeCurrentGuess();
            return;
        }
        if (!isValidWord(currentGuess)) {
            shakeCurrentGuess();
            return;
        }
        setGuessesCallback([...guesses, currentGuess]);
        dispatch({ type: "clear" });

        if (currentGuess === solution) {
            setGameCompletion("won");
            setTimeout(() => showToast("You truly are the Rune Master!"), 1500);
            return;
        }
        if (guesses.length + 1 === GAME_ROUNDS) {
            setGameCompletion("lost");
            setTimeout(() => {
                showToast(`You disappoint the Gods.\n${solution} was the word!`);
            }, 1500);
        }
    }, [currentGuess, guesses, dispatch, solution, showToast, shakeCurrentGuess, setGuessesCallback]);

    // Handle key press events
    const onKeyPress = useCallback(
        (key: string) => {
            if (gameCompletionState !== "active") return;

            if (key === BACKSPACE) {
                dispatch({ type: "backspace" });
                return;
            }
            if (key === ENTER) {
                submitWord();
                return;
            }
            if (key.length === 1 && /[a-zA-Z]/.test(key)) {
                dispatch({ type: "add", letter: key.toUpperCase() });
            }
        },
        [gameCompletionState, dispatch, submitWord]
    );

    // Listen for physical keyboard events
    useEffect(() => {
        const onKeyDownEvt = (evt: KeyboardEvent) => onKeyPress(evt.key);
        window.addEventListener("keydown", onKeyDownEvt);
        return () => window.removeEventListener("keydown", onKeyDownEvt);
    }, [onKeyPress]);

    // --- Tile and Keyboard State ---

    // Compute tile states for each guess row
    const guessIdxToTileStates = Array.from({ length: GAME_ROUNDS }, (_, idx) => {
        const isSubmitted = idx < guesses.length;
        return getTileStates(solution, guesses[idx], isSubmitted);
    });

    // Compute keyboard letter states
    const letterToLetterState: Record<string, LetterState> = {};
    guessIdxToTileStates.forEach((tileStates, idx) => {
        const guess = guesses[idx];
        if (!guess) return;
        tileStates.forEach((tileState, letterIdx) => {
            const letter = guess[letterIdx];
            if (tileState === "correct" || letterToLetterState[letter] === "correct") {
                letterToLetterState[letter] = "correct";
            } else if (tileState === "outofplace" || letterToLetterState[letter] === "outofplace") {
                letterToLetterState[letter] = "outofplace";
            } else if (tileState === "incorrect") {
                letterToLetterState[letter] = "incorrect";
            }
        });
    });

    // --- Render ---

    return (
        <div
            className="flex justify-around items-around"
            role="main"
            aria-label="Rune Master Game"
            aria-live="polite"
        >
            {toastText && (
            <div
                className="bg-parchment z-10 w-xs md:w-lg flex flex-col justify-center items-center animate-fade-in absolute p-2 mt-20"
                role="status"
                aria-live="assertive"
                aria-atomic="true"
            >
                <span className="w-60 md:w-75 text-lg md:text-2xl font-bold text-center">
                {toastText}
                </span>
            </div>
            )}
            <div
            className="flex flex-col items-center justify-start mt-2"
            role="region"
            aria-label="Game board and keyboard"
            >
            <div
                className="flex flex-col m-2"
                role="grid"
                aria-label="Guess rows"
                aria-rowcount={GAME_ROUNDS}
            >
                {Array.from({ length: GAME_ROUNDS }).map((_, idx) => {
                const isCurrentGuess = idx === guesses.length;
                return (
                    <GuessRow
                    key={idx}
                    guess={isCurrentGuess ? currentGuess : guesses[idx]}
                    letterStates={guessIdxToTileStates[idx]}
                    shake={shakeCurrentRow && isCurrentGuess}
                    data-testid={`row-${idx}`}
                    aria-rowindex={idx + 1}
                    />
                );
                })}
            </div>
            <Keyboard
                onKeyPress={onKeyPress}
                letterToLetterState={letterToLetterState}
                aria-label="On-screen keyboard"
            />
            </div>
        </div>
    );
};

import classNames from "classnames";
import { GAME_WORD_LENGTH, LetterState } from "../constants";
import { useEffect, useState } from "react";

type Props = {
    guess: string | undefined;
    letterStates: Array<LetterState>;
    shake: boolean;
    'data-testid'?: string; // <-- allow forwarding test id
};

/**
 * GuessRow component renders a row of tiles for the current guess.
 */
export const GuessRow = ({ guess, letterStates, shake, 'data-testid': dataTestId }: Props) => (
    <div
        className={classNames("flex gap-[1px]", { 'animate-shake': shake })}
        role="row"
        aria-rowindex={1}
        data-testid={dataTestId} // <-- apply test id to row container
    >
        {Array.from({ length: GAME_WORD_LENGTH }).map((_, idx) => (
            <Tile
                key={idx}
                idx={idx}
                letter={guess ? guess[idx] : ''}
                state={letterStates[idx]}
            />
        ))}
    </div>
);

type TileProps = {
    letter: string;
    state: LetterState;
    idx: number;
};

/**
 * Tile component represents a single letter tile in a guessing game row.
 */
export const Tile = ({ letter, state, idx }: TileProps) => {
    const [revealColour, setRevealColour] = useState(false);
    const animationDelay = idx * 150;

    useEffect(() => {
        if (state !== 'default') {
            const timeout = setTimeout(() => setRevealColour(true), animationDelay + 300);
            return () => clearTimeout(timeout);
        }
    }, [state, animationDelay]);

    const tileClass = classNames(
        {
            "default-tile-text md:text-xl lg:text-2xl pt-1": !letter,
            "default-tile-text animate-pop md:text-xl lg:text-2xl pt-1": !!letter && state === 'default',
            "default-tile-text animate-flip md:text-xl lg:text-2xl pt-1": state !== 'default' && !!letter,
            "default-tile-text2 md:text-xl lg:text-2xl pt-1": state === 'default',
            "correct-tile-text md:text-xl lg:text-2xl pt-1": state === 'correct' && revealColour,
            "incorrect-tile-text md:text-xl lg:text-2xl pt-1": state === 'incorrect' && revealColour,
            "oop-tile-text md:text-xl lg:text-2xl pt-1": state === 'outofplace' && revealColour,
        },
        'w-8 h-12 xl:w-10 xl:h-14 md:text-xl lg:text-2xl pt-1 flex justify-center items-center transition-all duration-200'
    );

    return (
        <div
            style={{ animationDelay: state === 'default' ? '0ms' : `${animationDelay}ms` }}
            className={tileClass}
            role="gridcell"
            aria-label={letter ? `Letter ${letter}, ${state}` : "Empty tile"}
            aria-selected={!!letter}
        >
            {letter}
        </div>
    );
};

import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, fireEvent, screen } from "@testing-library/react";
import { Header } from "./Header";
import '@testing-library/jest-dom'

describe("Header", () => {
    beforeEach(() => {
        vi.restoreAllMocks();
    });

    it("renders title, logo, and buttons", () => {
    render(<Header />);
    expect(screen.getByRole('heading', { name: /rune master/i })).toBeInTheDocument();
    expect(screen.getByTestId('logo')).toBeInTheDocument();
    expect(screen.getByLabelText(/start new game/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/open info modal/i)).toBeInTheDocument();
});

    it("reloads the page when new game button is clicked", () => {
        const reloadMock = vi.fn();
        vi.stubGlobal("window", { location: { reload: reloadMock } });
        render(<Header />);
        fireEvent.click(screen.getByLabelText(/start new game/i));
        expect(reloadMock).toHaveBeenCalled();
    });

    it("shows and hides the modal on info button and close", () => {
        render(<Header />);
        // Modal should not be visible initially
        expect(screen.queryByRole("dialog")).not.toBeInTheDocument();

        // Open modal
        fireEvent.click(screen.getByLabelText(/open info modal/i));
        expect(screen.getByRole("dialog")).toBeInTheDocument();

        // Close modal
        fireEvent.click(screen.getByRole("button", { name: /close/i }));
        expect(screen.queryByRole("dialog")).not.toBeInTheDocument();
    });
});

import { useState } from "react";
import { GiFireGem, GiScrollUnfurled } from "react-icons/gi";
import { MdFiberNew } from "react-icons/md";
import { Modal } from "./Modal";

type Props = {};

/**
 * Header component for the Rune Master application.
 *
 * Renders the top navigation bar with the game title, icons, and action buttons.
 * Includes a button to start a new game (reloads the page) and a button to open a modal.
 *
 * @param _props - Component props (currently unused).
 * @returns The header JSX element with navigation and modal controls.
 */
export const Header = (_props: Props) => {
    const [showModal, setShowModal] = useState(false);

    const handleNewGame = () => {
        window.location.reload();
    };

    const handleOpenModal = () => {
        setShowModal(true);
    };

    const handleCloseModal = () => {
        setShowModal(false);
    };

    return (
        <>
            <header
            className="flex justify-between items-center w-[100vw] h-12 border-b border-teal-600 p-2 bg-teal-900/60"
            role="banner"
            aria-label="Main Header"
            >
            {/* Left: Logo */}
            <div className="flex items-center" role="img" aria-label="Rune Master Logo">
                <span
                className="text-yellow-500 text-3xl md:text-4xl text-shadow-scroll"
                aria-hidden="true"
                data-testid="logo"
                >
                <GiFireGem />
                </span>
                <div className="w-12 md:w-14" aria-hidden="true" />
            </div>

            {/* Center: Title */}
            <h1
                className="relative text-2xl md:text-4xl bg-gradient-to-tl from-yellow-600 via-yellow-300 to-yellow-600 inline-block text-transparent bg-clip-text"
                id="app-title"
            >
                Rune Master
            </h1>

            {/* Right: Action Buttons */}
            <div className="flex items-center" role="group" aria-label="Header Actions">
                <button
                className="text-yellow-500 text-3xl md:text-4xl text-shadow-scroll px-2"
                onClick={handleNewGame}
                aria-label="Start New Game"
                aria-controls="app-title"
                type="button"
                >
                <MdFiberNew aria-hidden="true" focusable="false" />
                </button>
                <button
                className="text-yellow-500 text-2xl md:text-3xl text-shadow-scroll"
                onClick={handleOpenModal}
                aria-label="Open Info Modal"
                aria-haspopup="dialog"
                aria-expanded={showModal}
                aria-controls="info-modal"
                type="button"
                >
                <GiScrollUnfurled aria-hidden="true" focusable="false" />
                </button>
            </div>
            </header>

            {/* Modal */}
            <Modal showModal={showModal} onClose={handleCloseModal} />
        </>
    );
};

import { describe, it, expect, vi } from "vitest";
import { render, fireEvent, screen } from "@testing-library/react";
import { Keyboard, Key } from "./Keyboard";
import { BACKSPACE, ENTER } from "../constants";
import '@testing-library/jest-dom';

describe("Keyboard interactions", () => {
    it("calls onKeyPress with correct letter when a key is clicked", () => {
        const onKeyPress = vi.fn();
        render(<Keyboard onKeyPress={onKeyPress} letterToLetterState={{}} />);
        fireEvent.click(screen.getByText("Q"));
        expect(onKeyPress).toHaveBeenCalledWith("Q");
        fireEvent.click(screen.getByText(ENTER));
        expect(onKeyPress).toHaveBeenCalledWith(ENTER);
    });

    it("calls onKeyPress when Key is clicked", () => {
        const onKeyPress = vi.fn();
        render(<Key letter="B" onKeyPress={onKeyPress} letterState="default" />);
        fireEvent.click(screen.getByText("B"));
        expect(onKeyPress).toHaveBeenCalledWith("B");
    });

    it("calls onKeyPress for BACKSPACE", () => {
        const onKeyPress = vi.fn();
        render(<Key letter={BACKSPACE} onKeyPress={onKeyPress} letterState="default" />);
        fireEvent.click(screen.getByRole("button", { name: "Backspace" }));
        expect(onKeyPress).toHaveBeenCalledWith(BACKSPACE);
    });
});

